# Lesson 1: opening, part 1 (what a bond is) and part 2 (value of a bond with one repayment: question 1 of the lesson file).
# Figures are checked here, so a typo stops the build.
assert round(sum(5 / 1.07 ** t for t in range(1, 6)) + 105 / 1.07 ** 6, 4) == 90.4669
assert round(107 / 1.07, 6) == 100 and round(114.49 / 1.07 ** 2, 6) == 100


def DT(head, rows, start=1, foot=None):
    """A discounting table revealed one row per click. rows: cells; a cell is text, or (result, how it was computed)."""
    n = start
    h = ''.join(f'<th>{TX(x)}</th>' for x in head)
    b = ''
    for r in rows:
        tds = ''.join(f'<td><b class="gv">{TX(c[0])}</b><span class="gm">{TX(c[1])}</span></td>' if isinstance(c, tuple) else f'<td><b class="gv">{TX(c)}</b></td>' for c in r)
        b += f'<tr class="st" data-n="{n * 10}">{tds}</tr>'
        n += 1
    if foot:
        b += f'<tr class="st tot" data-n="{n * 10}">' + ''.join(f'<td><b class="gv">{TX(c)}</b></td>' for c in foot) + '</tr>'
        n += 1
    return f'<table class="tbl2 steptbl dt">{"<tr>" + h + "</tr>"}{b}</table>', n


